{
  "typography": {
    "caption": {
      "fontSize": {
        "pointer": 11,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 16
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontSize": {
        "pointer": 12,
        "touch": 13
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontSize": {
        "pointer": 13,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontSize": {
        "pointer": 14,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 500,
      "letterSpacing": 0
    },
    "title": {
      "fontSize": {
        "pointer": 16,
        "touch": 16
      },
      "lineHeight": {
        "pointer": 24,
        "touch": 24
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontSize": {
        "pointer": 20,
        "touch": 22
      },
      "lineHeight": {
        "pointer": 28,
        "touch": 28
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 26,
        "touch": 28
      },
      "lineHeight": {
        "pointer": 32,
        "touch": 36
      },
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "container": "{radius-container}",
      "modal": "{radius-modal}"
    },
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 44
      },
      "density": {
        "pointer": {
          "pad": 12,
          "gap": 12
        },
        "touch": {
          "pad": 12,
          "gap": 12
        }
      },
      "item": {
        "pointer": {
          "inset": 4,
          "pad": 8
        },
        "touch": {
          "inset": 8,
          "pad": 8
        }
      },
      "control": {
        "pointer": {
          "padding": 8,
          "gap": 8,
          "dot": 6,
          "switch": "small"
        },
        "touch": {
          "padding": 8,
          "gap": 8,
          "dot": 8,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 28,
          "lg": 32
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "halo",
      "width": 3,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    },
    "control": {
      "selection": "pill",
      "field": "box",
      "choice": "well",
      "track": "sunk",
      "handle": "circle",
      "group": "track"
    }
  },
  "shape": {
    "curve": "continuous",
    "corners": {
      "button": "radius"
    }
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0,
      "focus": 0,
      "pressed": 0,
      "dragged": 0
    },
    "ripple": false,
    "pressed-opacity": 0.7,
    "rest-opacity": 0.5,
    "disabled": {
      "content": 0.5,
      "fill": false
    }
  },
  "transition": {
    "enter": {
      "duration": 420,
      "timingFunction": "out-cubic"
    }
  },
  "motion": {
    "fast": {
      "stiffness": 1218,
      "damping": 70
    },
    "default": {
      "stiffness": 520,
      "damping": 34
    },
    "slow": {
      "stiffness": 320,
      "damping": 30
    },
    "state": {
      "duration": 120,
      "timingFunction": "out-cubic"
    }
  },
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      },
      "inset": {
        "foreground": "{foreground}",
        "material": null
      },
      "raised": {
        "background": "{raised}",
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": null,
        "border-color": "{glass-edge}",
        "border-top-color": "{glass-edge}",
        "border-bottom-color": "{glass-edge}"
      },
      "overlay": {
        "background": "{popover}",
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": null
      },
      "modal": {
        "background": "{card}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      },
      "inverse": {
        "background": "{inverse}",
        "foreground": "{inverse-foreground}",
        "backdropFilter": "none",
        "material": null
      },
      "glass": {
        "foreground": "{foreground}",
        "border-color": "{glass-edge}",
        "material": null,
        "background": "{raised}"
      },
      "accent": {
        "foreground": "{primary-foreground}",
        "border-color": "{brand-edge}",
        "border-top-color": "{brand-edge}",
        "border-bottom-color": "{brand-edge}",
        "pressed-opacity": 0.88,
        "material": null
      },
      "knob": {
        "foreground": "{foreground}",
        "material": null,
        "background": "{knob}",
        "border-color": "transparent"
      },
      "hover": {
        "foreground": "{foreground}",
        "material": null,
        "background": "{hover}",
        "border-color": "{glass-edge}",
        "border-top-color": "{glass-edge}",
        "border-bottom-color": "{glass-edge}"
      },
      "pressed": {
        "foreground": "{foreground}",
        "material": null,
        "border-color": "{glass-edge}",
        "border-top-color": "{glass-edge}",
        "border-bottom-color": "{glass-edge}"
      },
      "disabled": {
        "background": "{raised}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      }
    },
    "light": {
      "card": {
        "shadow": "0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 12px 32px -14px oklch(0.3 0.06 265 / 0.28)"
      },
      "inset": {
        "shadow": "inset 0 1px 1.5px oklch(0.3 0.06 265 / 0.14), inset 0 -1px 0 oklch(1 0 0 / 0.85)"
      },
      "raised": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35), 0 1px 2px oklch(0.25 0.03 265 / 0.06)"
      },
      "overlay": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
        "border-color": "oklch(0.38 0.03 265 / 0.22)"
      },
      "modal": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)"
      },
      "inverse": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
        "border-color": "oklch(0.38 0.03 265 / 0.22)"
      },
      "glass": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35), 0 1px 2px oklch(0.25 0.03 265 / 0.06)",
        "backdropFilter": "blur(14px) saturate(180%)"
      },
      "accent": {
        "background": "oklch(from {primary} l c h / 0.88)",
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.3), inset 0 -1px 0 oklch(0 0 0 / 0.203), inset 0 0 0 1px oklch(1 0 0 / 0.07), 0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 8px 18px -9px oklch(0.3 0.06 265 / 0.28)"
      },
      "knob": {
        "shadow": "0 1px 2px oklch(0.25 0.03 265 / 0.06)"
      },
      "hover": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35), 0 1px 2px oklch(0.25 0.03 265 / 0.06)"
      },
      "pressed": {
        "shadow": "inset 0 1px 1.5px oklch(0.3 0.06 265 / 0.14), inset 0 -1px 0 oklch(1 0 0 / 0.85)",
        "background": "oklch(from {muted} l c h / 0.26)"
      },
      "disabled": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35), 0 1px 2px oklch(0.25 0.03 265 / 0.06)"
      }
    },
    "dark": {
      "card": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.1), 0 12px 32px -14px oklch(0 0 0 / 0.6)"
      },
      "inset": {
        "shadow": "inset 0 1px 1.5px oklch(0 0 0 / 0.38), inset 0 -1px 0 oklch(1 0 0 / 0.09)"
      },
      "raised": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04), 0 1px 2px oklch(0 0 0 / 0.1)"
      },
      "overlay": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
        "border-color": "oklch(1 0 0 / 0.06)"
      },
      "modal": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)"
      },
      "inverse": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
        "border-color": "oklch(1 0 0 / 0.06)"
      },
      "glass": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04), 0 1px 2px oklch(0 0 0 / 0.1)",
        "backdropFilter": "blur(14px)"
      },
      "accent": {
        "background": "oklch(from {primary} l c h / 0.86)",
        "shadow": "inset 0 1px 0 oklch(1 0 0), inset 0 -1px 0 oklch(0 0 0 / 0.099), inset 0 0 0 1px oklch(0 0 0 / 0.07), 0 1px 2px oklch(0 0 0 / 0.1), 0 8px 18px -9px oklch(0 0 0 / 0.6)"
      },
      "knob": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.1)"
      },
      "hover": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04), 0 1px 2px oklch(0 0 0 / 0.1)"
      },
      "pressed": {
        "shadow": "inset 0 1px 1.5px oklch(0 0 0 / 0.38), inset 0 -1px 0 oklch(1 0 0 / 0.09)",
        "background": "oklch(from {muted} l c h / 0.11)"
      },
      "disabled": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04), 0 1px 2px oklch(0 0 0 / 0.1)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": "0 1px 2px oklch(0.25 0.03 265 / 0.06)",
      "md": "0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 12px 32px -14px oklch(0.3 0.06 265 / 0.28)",
      "lg": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
      "xl": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
      "inset": "inset 0 1px 1.5px oklch(0.3 0.06 265 / 0.14), inset 0 -1px 0 oklch(1 0 0 / 0.85)",
      "edge": {
        "surface": "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35)",
        "accent": "inset 0 1px 0 oklch(1 0 0 / 0.3), inset 0 -1px 0 oklch(0 0 0 / 0.203), inset 0 0 0 1px oklch(1 0 0 / 0.07), 0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 8px 18px -9px oklch(0.3 0.06 265 / 0.28)"
      }
    },
    "dark": {
      "sm": "0 1px 2px oklch(0 0 0 / 0.1)",
      "md": "0 1px 2px oklch(0 0 0 / 0.1), 0 12px 32px -14px oklch(0 0 0 / 0.6)",
      "lg": "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
      "xl": "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
      "inset": "inset 0 1px 1.5px oklch(0 0 0 / 0.38), inset 0 -1px 0 oklch(1 0 0 / 0.09)",
      "edge": {
        "surface": "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04)",
        "accent": "inset 0 1px 0 oklch(1 0 0), inset 0 -1px 0 oklch(0 0 0 / 0.099), inset 0 0 0 1px oklch(0 0 0 / 0.07), 0 1px 2px oklch(0 0 0 / 0.1), 0 8px 18px -9px oklch(0 0 0 / 0.6)"
      }
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Solid Glass (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "Solid Glass (`deeplethe/solid-glass`, MIT): panes of smoky translucent glass with top-edge light rims, hairline glass borders, and ambient drop shadows (`state.press-scale: 1`).",
        "elevation": "Layered glass elevation: surfaces combine translucent fills (`alpha < 1` over page grounds), top-edge inset highlights, `--glass-edge` borders, soft shadows, and backdrop blur (`glass`, `menu`, `modal`, `tooltip`, `inverse`).",
        "dos": [
          "Keep press interactions flat (`state.press-scale: 1`); pressed panes deepen and drop shadow rather than shrinking.",
          "Keep gradient stops `transparent` on translucent `background` finishes so alpha is not doubled by the canvas."
        ],
        "donts": [
          "Do not stack opaque fills behind translucent glass gradients; keep the `background` layer `transparent` when the gradient carries the fill."
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Semantic typography roles referencing tier-specific font.size and font.line-height.",
    "caption": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.caption}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.label}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.title}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.headline}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.display}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles by layer, referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for in-page elements: buttons, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": "{dimension.radius.container}",
        "$description": "Corner radius for containers and overlays: cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": "{dimension.radius.modal}",
        "$description": "Corner radius for modal surfaces: dialogs, sheets, and drawers."
      }
    },
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "halo"
        }
      },
      "$description": "Focus ring geometry and style enum.",
      "width": {
        "$value": {
          "value": 3,
          "unit": "px"
        },
        "$description": "Focus ring stroke width."
      },
      "offset": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Focus ring outward offset from control bounds."
      }
    },
    "control": {
